import{_ as e,o as t,c as o,a0 as s}from"./chunks/framework.D7EjqxMK.js";const _=JSON.parse('{"title":"树思考 ToT/GoT","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/03_高级模式/03_树思考ToT GoT.md","filePath":"06-agent/03_高级模式/03_树思考ToT GoT.md"}'),n={name:"06-agent/03_高级模式/03_树思考ToT GoT.md"};function r(l,a,c,i,p,T){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="树思考-tot-got" tabindex="-1">树思考 ToT/GoT <a class="header-anchor" href="#树思考-tot-got" aria-label="Permalink to &quot;树思考 ToT/GoT&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块三 · 03_高级模式 · 第 3 节 <strong>难度</strong>：⭐⭐ | <strong>前置知识</strong>：ReAct 模式</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>**ToT（Tree of Thought）**将 LLM 的推理从线性扩展为树状结构。每个节点是一个「思考」，LLM 评估每个分支的质量，选择最有希望的分支继续。</p><p>**GoT（Graph of Thought）**进一步将树扩展为图，允许思考之间交叉引用。</p><h3 id="tot-vs-cot-vs-react" tabindex="-1">ToT vs CoT vs ReAct <a class="header-anchor" href="#tot-vs-cot-vs-react" aria-label="Permalink to &quot;ToT vs CoT vs ReAct&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CoT:    A → B → C → D  （线性推理）</span></span>
<span class="line"><span>ToT:    A → [B C D] → E → F  （树状分支）</span></span>
<span class="line"><span>GoT:    A ↔ B ↔ C ↔ D  （图状交叉）</span></span>
<span class="line"><span>ReAct:  推理 → 行动 → 观察 → 推理  （交替）</span></span></code></pre></div><hr><h2 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h2><ul><li><a href="https://gitcode.csdn.net/69c1ee540a2f6a37c599e1e8.html" target="_blank" rel="noreferrer">ReAct、Plan-and-Execute、Reflection、Multi-Agent 工程范式</a></li></ul>`,11)])])}const d=e(n,[["render",r]]);export{_ as __pageData,d as default};
